\documentclass[11pt]{amsart}
\usepackage{amsmath, amssymb, amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\flatDeg}{\operatorname{flatDeg}}
\newcommand{\sharpDeg}{\operatorname{sharpDeg}}
\newcommand{\Z}{\mathbb{Z}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\Q}{\mathbb{Q}}

\title{Sharp/Flat Supersingular Degree Sequences at a General Prime}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}

\begin{abstract}
For an elliptic curve with good supersingular reduction at a prime $p$, the sharp and
flat characteristic degrees of Pollack--Kobayashi type grow, along the cyclotomic
$\Z_p$-tower, like partial sums of powers of $p$ in base $p^2$. At the prime $p = 2$
this growth is governed by the classical Jacobsthal recurrence
$J_{n+2} = J_{n+1} + 2J_n$, and the flat degree is exactly the even-indexed Jacobsthal
number. We isolate the elementary arithmetic skeleton of this phenomenon and extend it
verbatim to an arbitrary supersingular prime $p$. Replacing the Jacobsthal sequence by
the two-parameter \emph{generalised Jacobsthal sequence}
$q_{n+2} = (p-1)q_{n+1} + p q_n$ (with $q_0 = 0$, $q_1 = 1$) and base $4$ by base
$p^2$, we prove: the closed form $(p+1)q_n = p^n - (-1)^n$; the consecutive-sum
identity $q_n + q_{n+1} = p^n$; the base-$p^2$ flat-degree closed form
$(p^2 - 1)\flatDeg_p(n) + 1 = p^{2n}$; the sharp/flat ratio
$\sharpDeg_p(n) = p\,\flatDeg_p(n)$; and the \emph{bridge}
$q_{2n} = (p-1)\flatDeg_p(n)$ linking the recurrence to the honest base-$p^2$ growth of
the degrees. Every statement specialises, at $p = 2$, to the classical Jacobsthal
identities. The unifying mechanism is the factorisation $p^2 - 1 = (p+1)(p-1)$, which
reveals that the apparent dependence of the classical formula on the accident
$p - 1 = 1$ was illusory.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Context}
The Iwasawa theory of an elliptic curve $E/\Q$ studies how arithmetic invariants of
$E$ vary along the cyclotomic $\Z_p$-tower
$\Q \subset \Q(\mu_p) \subset \Q(\mu_{p^2}) \subset \cdots$. When $E$ has good
\emph{ordinary} reduction at $p$, a single $p$-adic $L$-function and a single
characteristic ideal control the growth of the Selmer groups, yielding one
$\lambda$-invariant and one $\mu$-invariant. When $E$ has good \emph{supersingular}
reduction --- an infinite but density-zero set of primes for a fixed curve --- the
classical $p$-adic $L$-function fails to be integral, and the theory bifurcates.
Following Pollack and Kobayashi, one introduces a \emph{pair} of well-behaved objects:
the \emph{sharp} ($\sharp$) and \emph{flat} ($\flat$) $p$-adic $L$-functions and their
associated plus/minus Selmer groups, each with its own $\lambda$-invariant.

A recurrent computational observation is that the characteristic degrees attached to
these sharp and flat objects grow, level by level, as partial sums of powers of $p$
segregated by parity of exponent. At $p = 2$ these sums coincide with the classical
Jacobsthal numbers. The purpose of this paper is to extract the underlying elementary
arithmetic, prove it rigorously, and show that it holds for every prime once the base
$p^2$ and the two-parameter recurrence are used.

\subsection{Results}
We prove, for an arbitrary prime $p$ (the identities hold over $\Z$ for arbitrary
integer $p$ under the stated non-degeneracy):
\begin{enumerate}
  \item \textbf{Jacobsthal closed form} (Theorem~\ref{thm:closed}): $(p+1)q_n = p^n - (-1)^n$.
  \item \textbf{Consecutive-sum law} (Theorem~\ref{thm:consec}): $q_n + q_{n+1} = p^n$.
  \item \textbf{Base-$p^2$ flat-degree closed form} (Theorem~\ref{thm:flatclosed}):
        $(p^2-1)\flatDeg_p(n) + 1 = p^{2n}$.
  \item \textbf{Sharp/flat ratio} (Theorem~\ref{thm:ratio}): $\sharpDeg_p(n) = p\,\flatDeg_p(n)$.
  \item \textbf{Bridge} (Theorem~\ref{thm:bridge}): $q_{2n} = (p-1)\flatDeg_p(n)$.
\end{enumerate}

\subsection{The unifying mechanism}
The single fact that drives every comparison is the factorisation
$p^2 - 1 = (p+1)(p-1)$. The factor $p+1$ is the denominator in the Jacobsthal closed
form; the factor $p-1$ is the extra coefficient that appears on the degree side; their
product $p^2 - 1$ is exactly the multiplier that telescopes the base-$p^2$ geometric
sum. This is why the bridge involves even Jacobsthal indices and the factor $p-1$, and
why the classical $p = 2$ formula --- in which $p-1 = 1$ vanishes silently --- looked
deceptively like a fact about the number $2$.

\section{Definitions}

Throughout, $p$ denotes a prime; the arithmetic identities hold over $\Z$ for arbitrary
integer $p$ under the indicated non-degeneracy hypotheses.

\begin{definition}[Generalised Jacobsthal sequence]
The generalised Jacobsthal sequence $q_\bullet : \N \to \Z$ attached to $p$ is defined by
\[ q_0 = 0, \qquad q_1 = 1, \qquad q_{n+2} = (p-1)q_{n+1} + p\,q_n \quad (n \ge 0). \]
Its characteristic polynomial is $x^2 - (p-1)x - p = (x-p)(x+1)$, with roots $p$ and
$-1$. At $p = 2$ the recurrence is the classical Jacobsthal recurrence
$q_{n+2} = q_{n+1} + 2q_n$, producing $0,1,1,3,5,11,21,43,85,\dots$.
\end{definition}

\begin{definition}[Flat degree]
For $p, n \in \N$, the flat characteristic degree is the base-$p^2$ partial sum
\[ \flatDeg_p(n) = \sum_{i=0}^{n-1} p^{2i} = 1 + p^2 + p^4 + \cdots + p^{2(n-1)}. \]
\end{definition}

\begin{definition}[Sharp degree]
For $p, n \in \N$, the sharp characteristic degree is the odd-exponent partial sum
\[ \sharpDeg_p(n) = \sum_{i=0}^{n-1} p^{2i+1} = p + p^3 + p^5 + \cdots + p^{2n-1}. \]
\end{definition}

\section{The generalised Jacobsthal sequence}

\begin{theorem}[Closed form]\label{thm:closed}
For every $n \ge 0$, $\;(p+1)q_n = p^n - (-1)^n.$
\end{theorem}

\begin{proof}
Strong induction on $n$. The base cases are direct: $(p+1)q_0 = 0 = p^0 - (-1)^0$ and
$(p+1)q_1 = p+1 = p^1 - (-1)^1$. For the step at $n+2$, apply the recurrence and the
hypotheses at $n+1$ and $n$:
\[ (p+1)q_{n+2} = (p-1)\bigl(p^{n+1} - (-1)^{n+1}\bigr) + p\bigl(p^n - (-1)^n\bigr). \]
The power terms give $(p-1)p^{n+1} + p^{n+1} = p^{n+2}$; the sign terms give
$(p-1)(-1)^n - p(-1)^n = -(-1)^n = -(-1)^{n+2}$. Hence
$(p+1)q_{n+2} = p^{n+2} - (-1)^{n+2}$.
\end{proof}

\begin{theorem}[Consecutive-sum law]\label{thm:consec}
If $p + 1 \ne 0$, then $\;q_n + q_{n+1} = p^n$ for every $n \ge 0$.
\end{theorem}

\begin{proof}
Multiply by $p+1$ and apply Theorem~\ref{thm:closed} twice:
\[ (p+1)(q_n + q_{n+1}) = \bigl(p^n - (-1)^n\bigr) + \bigl(p^{n+1} - (-1)^{n+1}\bigr)
   = p^n + p^{n+1} = (p+1)p^n, \]
since $(-1)^n + (-1)^{n+1} = 0$. Cancel the non-zero factor $p+1$.
\end{proof}

\section{The base-$p^2$ degree sequences}

\begin{lemma}[One-step growth]\label{lem:step}
For every $n \ge 0$, $\;\flatDeg_p(n+1) = \flatDeg_p(n) + p^{2n}.$
\end{lemma}

\begin{proof}
Immediate: the sum over $i < n+1$ is the sum over $i < n$ plus the top term $p^{2n}$.
\end{proof}

\begin{theorem}[Base-$p^2$ closed form]\label{thm:flatclosed}
For every $n \ge 0$,
\[ (p^2 - 1)\flatDeg_p(n) + 1 = p^{2n}, \]
equivalently, in subtraction-free form, $\;p^2\flatDeg_p(n) + 1 = \flatDeg_p(n) + p^{2n}.$
\end{theorem}

\begin{proof}
Induction on $n$. For $n = 0$, both sides equal $1$. Assuming the identity at $n$, use
Lemma~\ref{lem:step}:
\[ (p^2-1)\flatDeg_p(n+1) + 1 = \bigl[(p^2-1)\flatDeg_p(n) + 1\bigr] + (p^2-1)p^{2n}
   = p^{2n} + (p^2-1)p^{2n} = p^{2(n+1)}. \qedhere \]
\end{proof}

\begin{theorem}[Sharp/flat ratio]\label{thm:ratio}
For every $n \ge 0$, $\;\sharpDeg_p(n) = p\,\flatDeg_p(n).$
\end{theorem}

\begin{proof}
Factor a single $p$ out of each term:
$\sharpDeg_p(n) = \sum_{i<n} p^{2i+1} = p\sum_{i<n} p^{2i} = p\,\flatDeg_p(n)$.
\end{proof}

\section{The bridge}

\begin{theorem}[Bridge]\label{thm:bridge}
For every $n \ge 0$ (with $p+1 \ne 0$), $\;q_{2n} = (p-1)\flatDeg_p(n).$
\end{theorem}

\begin{proof}
Evaluate Theorem~\ref{thm:closed} at the even index $2n$:
$(p+1)q_{2n} = p^{2n} - (-1)^{2n} = p^{2n} - 1$. By Theorem~\ref{thm:flatclosed},
$p^{2n} - 1 = (p^2-1)\flatDeg_p(n)$. Factoring $p^2 - 1 = (p+1)(p-1)$ gives
$(p+1)q_{2n} = (p+1)(p-1)\flatDeg_p(n)$; cancel $p+1$.
\end{proof}

The proof isolates the role of each factor of $p^2 - 1$: the $p+1$ is the Jacobsthal
denominator that cancels, and the $p-1$ is the residue that survives on the degree
side. Even-indexed generalised Jacobsthal numbers, and only those, track the flat
degree.

\section{Specialisation to $p = 2$}

Setting $p = 2$ recovers the classical picture. The recurrence becomes
$q_{n+2} = q_{n+1} + 2q_n$ with $q_\bullet = 0,1,1,3,5,11,21,43,85,\dots$; the closed
form becomes $3q_n = 2^n - (-1)^n$; the consecutive-sum law becomes $q_n + q_{n+1} =
2^n$; the degrees are the base-$4$ sums with $\sharpDeg_2(n) = 2\flatDeg_2(n)$; the
base-$p^2$ closed form becomes $3\flatDeg_2(n) + 1 = 4^n$; and the bridge becomes
\[ q_{2n} = (2-1)\flatDeg_2(n) = \flatDeg_2(n), \]
i.e.\ the even Jacobsthal numbers \emph{equal} the flat degrees. Because $p - 1 = 1$ at
$p = 2$, the factor $p-1$ disappears, making the flat degree equal to --- rather than
merely proportional to --- the even Jacobsthal number. The present treatment shows this
was an artefact of the prime $2$.

\section{Applications and discussion}

Under the dictionary in which $\flatDeg_p$ and $\sharpDeg_p$ model the level-$n$
characteristic degrees of the flat and sharp Pollack--Kobayashi $p$-adic $L$-functions:
Theorem~\ref{thm:flatclosed} says the flat degree grows so that its base-$p^2$ digit
length increases by one per level; Theorem~\ref{thm:ratio} says the sharp and flat
degrees are never independent; and Theorem~\ref{thm:bridge} lets one compute flat
degrees via the fast Jacobsthal recurrence. These form the arithmetic skeleton on which
the analytic and cohomological machinery of supersingular Iwasawa theory --- Coleman
maps, Pollack's $\omega_n^\pm$, Sprung's sharp/flat decomposition, and Matsuno's twist
formula --- is hung.

Several extensions push the scaffold toward genuine Iwasawa theory: a uniform local
depth-weight law $m_\ell = v_p((\ell^{p^2-1}-1)/(p^2-1))$ with aggregate weight
$(p-1)\flatDeg_p(\omega(D))$; multiplicativity of the degree pair under coprime twisting
via the base-$p^2$ convolution $\flatDeg(mn) = \flatDeg(m) + p^{2\omega(m)}\flatDeg(n)$;
a parity statement for the sharp/flat $\lambda$-difference obstructed only at $p = 2$ by
the $(-1)^n$ term; and, ultimately, the replacement of the modelled degrees by genuine
$\lambda$- and $\mu$-invariants extracted via Weierstrass preparation, together with the
Coleman-map identification of $\omega_n^\pm$.

\section{Conclusion}

The generalised Jacobsthal recurrence and its consequences form a complete,
prime-independent description of the growth of sharp and flat supersingular degrees.
The single factorisation $p^2 - 1 = (p+1)(p-1)$ explains both why the theory works and
why the classical $p = 2$ case appeared, misleadingly, to be special.

\end{document}

