from __future__ import annotations

def flat_degree_closed(p: int, n: int) -> int:
    """Flat degree via the base-p^2 closed form (p^(2n)-1)//(p^2-1).

    Derived from (p^2-1) flatDeg + 1 = p^(2n). For p=1 the geometric
    series degenerates and the flat degree is simply n.
    Complexity: one modular power, O(log n) multiplications.
    """
    if p == 1:
        return n
    return (p ** (2 * n) - 1) // (p ** 2 - 1)

def sharp_degree_closed(p: int, n: int) -> int:
    """Sharp degree via the ratio sharpDeg = p * flatDeg."""
    return p * flat_degree_closed(p, n)

